import os, json, math

# Physical constants (SI)
G = 6.67430e-11            # m^3 kg^-1 s^-2
c = 2.99792458e8          # m s^-1
M_sun = 1.98847e30        # kg

# Helper to load a GWTC catalog via environment variable
def load_gwtc_catalog():
    path = os.getenv('GWTC_CATALOG_PATH')
    if path and os.path.isfile(path):
        try:
            with open(path, 'r') as f:
                return json.load(f)
        except Exception as e:
            print(f"Failed to load catalog: {e}")
    # Small synthetic fallback – may be insufficient for real analysis
    return {
        "events": [
            {"mass_1_source": 30.0, "mass_2_source": 35.0, "final_mass_source": 62.0},
            {"mass_1_source": 15.0, "mass_2_source": 20.0, "final_mass_source": 33.0}
        ]
    }

def compute_radiated_fraction(event):
    m1 = event.get("mass_1_source")
    m2 = event.get("mass_2_source")
    mf = event.get("final_mass_source")
    if None in (m1, m2, mf):
        return None
    total_initial = m1 + m2
    # Guard against non-positive initial mass
    if total_initial <= 0:
        return None
    epsilon = (total_initial - mf) / total_initial
    # Physical bound epsilon <= 0.25 (mass loss cannot exceed 25% of initial total)
    return max(0.0, min(epsilon, 0.25))

def main():
    catalog = load_gwtc_catalog()
    epsilons = []
    for ev in catalog.get("events", []):
        eps = compute_radiated_fraction(ev)
        if eps is not None:
            epsilons.append(eps)
    if not epsilons:
        print("No valid events found.")
        return
    max_eps = max(epsilons)
    print(f"Maximum radiated mass fraction across events: {max_eps:.4f}")
    if max_eps <= 0.25:
        print("PASS: All events respect the 25% radiated mass bound.")
    else:
        print("FAIL: Some events exceed the 25% radiated mass bound.")

if __name__ == "__main__":
    main()

