G = 6.67430e-11          # m^3 kg^-1 s^-2
c = 2.99792458e8        # m s^-1
hbar = 1.054571817e-34  # J s
k_B = 1.380649e-23      # J K^-1
M_sun = 1.98847e30      # kg

def schwarzschild_radius(M):
    return 2 * G * M / c**2

def photon_sphere_radius(M):
    return 1.5 * schwarzschild_radius(M)

def critical_impact_parameter(M):
    # b_crit = 3*sqrt(3)*GM/c^2  (impact parameter that separates capture and escape)
    return 3 * math.sqrt(3) * G * M / c**2

def horizon_area(M):
    r_s = schwarzschild_radius(M)
    return 4 * math.pi * r_s**2

def hawking_temperature(M):
    return hbar * c**3 / (8 * math.pi * G * M * k_B)

def planck_length():
    return math.sqrt(hbar * G / c**3)

def bh_entropy(M):
    r_s = schwarzschild_radius(M)
    A = horizon_area(M)
    l_p2 = planck_length()**2
    return A / (4 * l_p2)

def critical_impact_probability(M, N=10000):
    b_crit = critical_impact_parameter(M)
    b_max = 10 * b_crit  # safe upper bound
    hits = 0
    for _ in range(N):
        b = random.uniform(0, b_max)
        if b <= b_crit:
            hits += 1
    return hits / N

def main():
    masses = [M_sun, 10 * M_sun, 100 * M_sun]
    print("=== Schwarzschild metrics & critical impact probability ===")
    for M in masses:
        r_s = schwarzschild_radius(M)
        r_ph = photon_sphere_radius(M)
        b_crit = critical_impact_parameter(M)
        prob = critical_impact_probability(M)
        print(f"M = {M:.3e} kg")
        print(f"  r_s = {r_s:.3e} m")
        print(f"  r_ph = {r_ph:.3e} m")
        print(f"  b_crit = {b_crit:.3e} m")
        print(f"  P(b <= b_crit) = {prob:.6f}\n")

if __name__ == "__main__":
    main()

