#!/usr/bin/env python3
import os, json, math, sys

# Physical constants (SI)
G = 6.67430e-11          # m^3 kg^-1 s^-2
c = 2.99792458e8        # m s^-1
M_sun = 1.98847e30      # kg

def load_gwtc_catalog():
    """Load the GWTC catalog from the path given in the environment variable.
    The catalog is expected to be a JSON file with keys:
        - events: a list of dictionaries, each containing at least the fields
            'mass_1_source' (float) and 'mass_2_source' (float).
    Returns a list of event dictionaries.
    """
    path = os.getenv('GWTC_CATALOG_PATH')
    if not path:
        sys.exit('ERROR: GWTC_CATALOG_PATH environment variable not set')
    try:
        with open(path, 'r') as f:
            catalog = json.load(f)
    except Exception as e:
        sys.exit(f'ERROR: Could not read catalog at {path}: {e}')
    if 'events' not in catalog:
        sys.exit('ERROR: Catalog does not contain an "events" list')
    return catalog['events']

def compute_mean_final_mass(events):
    """Compute the mean final mass (source‑frame) for a list of events.
    Returns the mean in kilograms.
    """
    total = 0.0
    count = 0
    for ev in events:
        m1 = ev.get('mass_1_source')
        m2 = ev.get('mass_2_source')
        if m1 is None or m2 is None:
            continue
        # Ensure values are positive
        if m1 <= 0 or m2 <= 0:
            continue
        total += (m1 + m2) * M_sun
        count += 1
    if count == 0:
        return float('nan')
    return total / count

if __name__ == '__main__':
    events = load_gwtc_catalog()
    mean_mass = compute_mean_final_mass(events)
    if math.isnan(mean_mass):
        print('No valid masses found in the catalog.')
    else:
        print(f"Mean final mass: {mean_mass:.2f} kg")
